<script setup>
import {computed,ref} from 'vue';import {useTimeline} from './useTimeline';import {sources,binsFor,clock,INCIDENT} from './data';
const {filtered,inspect}=useTimeline();const baseline=ref(INCIDENT-1800),eventStart=INCIDENT-60;
const windows=computed(()=>[{label:'A · חלון השוואה',start:Number(baseline.value)},{label:'B · חלון האירוע',start:eventStart}].map(w=>({...w,rows:sources.map(s=>({...s,bins:binsFor(filtered.value.filter(e=>e.source===s.id),w.start,w.start+300,20)}))})));
const max=computed(()=>Math.max(1,...windows.value.flatMap(w=>w.rows.flatMap(s=>s.bins.map(b=>b.count)))));
</script><template><div class="compare-toolbar"><label>נקודת השוואה <select v-model="baseline"><option :value="INCIDENT-1800">30 דקות לפני</option><option :value="INCIDENT-600">10 דקות לפני</option><option :value="INCIDENT+2400">מקבץ הארכוב המאוחר</option></select></label><span>חלונות עצמאיים של 5 דקות · גובה עמודה באותו סולם בשניהם</span></div><div class="comparison"><section v-for="w in windows" :key="w.label" class="comparison-window"><header><h3>{{w.label}}</h3><span dir="ltr">{{clock(w.start)}} — {{clock(w.start+300)}}</span></header><div v-for="s in w.rows" :key="s.id" class="compare-row"><strong>{{s.label}}</strong><div class="compare-bars" dir="ltr"><button v-for="b in s.bins" :key="b.start" :class="{alert:b.alert}" :style="{height:Math.max(3,b.count/max*34)+'px'}" :title="clock(b.start)+' · '+b.count+' רשומות · '+b.alert+' חריגות'" @click="inspect(b.start,b.end,{source:s.id})"></button></div><span>{{s.bins.reduce((n,b)=>n+b.count,0)}}</span></div><div class="relative-axis" dir="ltr"><span>+0:00</span><span>+2:30</span><span>+5:00</span></div></section></div></template>